#include <bits/stdc++.h>
using namespace std;

struct MaxFlowSolver {
    struct Edge {
        int from, to;
        long long flow, capacity;
    };
    int s, t;
    vector<Edge> edges;
    vector<int> adj[7100];
    int level[7100], current[7100];

    void reset() {
        edges.clear();
        for (int i = 0; i < 7100; ++i) {
            adj[i].clear();
        }
    }

    void addEdge(int u, int v, long long cap) {
        edges.push_back({u, v, 0, cap});
        edges.push_back({v, u, 0, 0});
        adj[u].push_back((int)edges.size() - 2);
        adj[v].push_back((int)edges.size() - 1);
    }

    bool buildLevelGraph() {
        memset(level, -1, sizeof(level));
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto &idx : adj[u]) {
                auto &e = edges[idx];
                if (e.capacity > e.flow && level[e.to] < 0) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    long long sendFlow(int u, long long flow) {
        if (u == t || flow == 0) return flow;
        long long totalSent = 0;
        for (int &i = current[u]; i < (int)adj[u].size(); ++i) {
            auto &e = edges[adj[u][i]];
            if (level[e.to] == level[u] + 1 && e.capacity > e.flow) {
                long long pushed = sendFlow(e.to, min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[adj[u][i] ^ 1].flow -= pushed;
                    totalSent += pushed;
                    flow -= pushed;
                    if (flow == 0) break;
                }
            }
        }
        return totalSent;
    }

    long long maxFlow() {
        long long totalFlow = 0;
        while (buildLevelGraph()) {
            for (int i = 0; i < 7100; ++i) current[i] = 0;
            totalFlow += sendFlow(s, LLONG_MAX);
        }
        return totalFlow;
    }
};

MaxFlowSolver solver;
char mazeX[14][14], mazeY[14][14];
bool visitedCells[14][14];
int distMap[14][14];
int n;
int targetIdx[103];

void performBFS(int x, int y) {
    std::queue<std::pair<std::pair<int, int>, int>> q;
    for (int i = 0; i < 14; ++i)
        for (int j = 0; j < 14; ++j)
            distMap[i][j] = 111;
    distMap[x][y] = 0;
    q.push({{x, y}, 0});
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        int cx = p.first.first, cy = p.first.second, d = p.second;
        if (visitedCells[cx][cy]) continue;
        visitedCells[cx][cy] = true;
        distMap[cx][cy] = d;
        for (int dir = 0; dir < 4; ++dir) {
            int nx = cx + dx[dir], ny = cy + dy[dir];
            if (nx <= 0 || nx > n || ny <= 0 || ny > n || visitedCells[nx][ny] || mazeX[nx][ny] == 'Y') continue;
            q.push({{nx, ny}, d + 1});
        }
    }
}

int getIdx(int level, int x, int y) {
    return level * n * n + (x - 1) * n + y;
}

int main() {
    int t, i, j, k;
    scanf("%d%d", &n, &t);
    for (i = 1; i <= n; ++i) scanf("%s", mazeX[i] + 1);
    for (i = 1; i <= n; ++i) scanf("%s", mazeY[i] + 1);
    solver.s = 0; solver.t = 7099;
    int startX = 0, startY = 0;
    for (i = 1; i <= n; ++i) {
        for (j = 1; j <= n; ++j) {
            if (mazeX[i][j] == 'Z') {
                startX = i; startY = j; break;
            }
        }
    }
    for (i = 1; i <= n * n; ++i) targetIdx[i] = 7098 - (n * n - i);
    performBFS(startX, startY);
    for (i = 1; i <= n; ++i) {
        for (j = 1; j <= n; ++j) {
            if (mazeX[i][j] >= '0' && mazeX[i][j] <= '9')
                solver.addEdge(solver.s, getIdx(0, i, j), mazeX[i][j] - '0');
            if (mazeY[i][j] >= '0' && mazeY[i][j] <= '9')
                solver.addEdge(targetIdx[getIdx(0, i, j)], solver.t, mazeY[i][j] - '0');
            solver.addEdge(getIdx(0, i, j), targetIdx[getIdx(0, i, j)], LLONG_MAX);
        }
    }
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    for (i = 1; i <= t; ++i) {
        for (j = 1; j <= n; ++j) {
            for (k = 1; k <= n; ++k) {
                if (mazeX[j][k] == 'Y' || mazeX[j][k] == 'Z') continue;
                for (int l = 0; l < 4; ++l) {
                    int tx = j + dx[l], ty = k + dy[l];
                    if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && mazeX[tx][ty] != 'Y' && mazeX[tx][ty] != 'Z') {
                        if (distMap[j][k] >= i && distMap[tx][ty] >= i) {
                            solver.addEdge(getIdx(i - 1, tx, ty), getIdx(i, j, k), LLONG_MAX);
                        }
                    }
                }
                solver.addEdge(getIdx(i, j, k), targetIdx[getIdx(0, j, k)], LLONG_MAX);
            }
        }
    }
    printf("%lld\n", solver.maxFlow());
    return 0;
}
